-- Test-only approved two-wheeler draft contract. Existing functions/policies stay intact.
-- Categories remain closed until a separate, verified activation migration.
begin;
set local lock_timeout = '5s';
set local statement_timeout = '60s';

create table public.vehicle_source_snapshots (
  id uuid primary key default gen_random_uuid(), source_file text not null,
  sha256 text not null check (sha256 ~ '^[0-9a-f]{64}$'), row_count integer not null check(row_count=830),
  unique(source_file,sha256)
);
create table public.vehicle_contract_versions (
  id uuid primary key default gen_random_uuid(), contract_key text not null unique,
  definition jsonb not null check(jsonb_typeof(definition)='object'),
  snapshot_id uuid not null references public.vehicle_source_snapshots(id), new_assignment_enabled boolean not null default false
);
create table public.vehicle_category_contracts (
  category_id uuid not null references public.categories(id), version_id uuid not null references public.vehicle_contract_versions(id),
  source_path jsonb not null, fields jsonb not null, source_provenance jsonb not null, display_order integer not null,
  primary key(category_id,version_id), check(jsonb_typeof(fields)='array'), check(jsonb_array_length(source_path)=3)
);
create table public.vehicle_brands (
  id uuid primary key default gen_random_uuid(), label text not null unique check(length(btrim(label))>0)
);
create table public.vehicle_models (
  id uuid primary key default gen_random_uuid(), brand_id uuid not null references public.vehicle_brands(id),
  label text not null check(length(btrim(label))>0), unique(brand_id,label), unique(id,brand_id)
);
create table public.vehicle_catalogue_rows (
  snapshot_id uuid not null references public.vehicle_source_snapshots(id), model_id uuid not null references public.vehicle_models(id),
  source_row integer not null check(source_row>=2), source_order integer not null check(source_order>=0),
  raw jsonb not null check(jsonb_typeof(raw)='object'), selection_enabled boolean not null default true,
  primary key(snapshot_id,model_id), unique(snapshot_id,source_row), check(source_row=source_order+2)
);
create table public.vehicle_registration_states (
  id uuid primary key default gen_random_uuid(), reference_key text not null unique,
  label text not null unique, kind text not null check(kind in ('state','ut')), source_url text not null
);
create table public.listing_vehicle_contexts (
  listing_id uuid primary key references public.listings(id) on delete cascade,
  category_id uuid not null, version_id uuid not null,
  mode text not null check(mode in ('unanswered','catalogue','unresolved','not_listed')),
  brand_id uuid references public.vehicle_brands(id), model_id uuid,
  brand_text text, model_text text, classification_review_required boolean not null default false,
  foreign key(category_id,version_id) references public.vehicle_category_contracts(category_id,version_id),
  foreign key(model_id,brand_id) references public.vehicle_models(id,brand_id),
  check((mode='unanswered' and model_id is null and brand_text is null and model_text is null)
    or (mode in ('catalogue','unresolved') and brand_id is not null and model_id is not null and brand_text is null and model_text is null)
    or (mode='not_listed' and brand_id is null and model_id is null and brand_text is not null and model_text is not null and length(btrim(brand_text)) between 1 and 100 and length(btrim(model_text)) between 1 and 150))
);

-- No inherited default grants: reference reads only, contexts owner-only with existing account/policy guards.
do $$ declare t text; begin
  foreach t in array array['vehicle_source_snapshots','vehicle_contract_versions','vehicle_category_contracts','vehicle_brands','vehicle_models','vehicle_catalogue_rows','vehicle_registration_states'] loop
    execute format('alter table public.%I enable row level security',t);
    execute format('revoke all on public.%I from public, anon, authenticated, service_role',t);
    execute format('grant select on public.%I to authenticated',t);
    execute format('create policy reference_read on public.%I for select to authenticated using (true)',t);
  end loop;
end $$;
alter table public.listing_vehicle_contexts enable row level security;
revoke all on public.listing_vehicle_contexts from public,anon,authenticated,service_role;
grant select,insert,update on public.listing_vehicle_contexts to authenticated;
create policy vehicle_context_read on public.listing_vehicle_contexts for select to authenticated using (
  exists(select 1 from public.listings l where l.id=listing_id and l.seller_id=(select auth.uid()))
);
create policy vehicle_context_insert on public.listing_vehicle_contexts for insert to authenticated with check (
  exists(select 1 from public.listings l where l.id=listing_id and l.seller_id=(select auth.uid()) and l.status='draft')
  and app_security.get_account_status((select auth.uid()))='active' and app_security.has_current_policy_acceptance((select auth.uid()))
);
create policy vehicle_context_update on public.listing_vehicle_contexts for update to authenticated using (
  exists(select 1 from public.listings l where l.id=listing_id and l.seller_id=(select auth.uid()) and l.status='draft')
  and app_security.get_account_status((select auth.uid()))='active' and app_security.has_current_policy_acceptance((select auth.uid()))
) with check (
  exists(select 1 from public.listings l where l.id=listing_id and l.seller_id=(select auth.uid()) and l.status='draft')
  and app_security.get_account_status((select auth.uid()))='active' and app_security.has_current_policy_acceptance((select auth.uid()))
);

-- UTC date/year, strict optional answers, safe JSON numbers. Safeguards are implementation limits.
create function app_security.validate_vehicle_answers(a jsonb, fields jsonb, previous jsonb default '{}'::jsonb)
returns jsonb language plpgsql set search_path='' as $$
declare k text; v jsonb; n numeric; d date; status text; normalized jsonb := a; today date := (statement_timestamp() at time zone 'UTC')::date;
begin
  if jsonb_typeof(a) is distinct from 'object' then raise exception 'Vehicle answers must be an object'; end if;
  for k,v in select * from jsonb_each(a) loop
    if not fields ? k or k in ('brand','model','price','negotiable') then raise exception 'Unexpected or duplicate authority field: %',k; end if;
    if k in ('year','km_driven') then
      if jsonb_typeof(v) is distinct from 'object' then raise exception '% needs an answer state',k; end if;
      status:=v->>'state';
      if status is null or status not in ('known','unknown','unanswered') or exists(select 1 from jsonb_object_keys(v) x where x not in ('state','value')) then raise exception 'Invalid answer state for %',k; end if;
      if status='known' then
        if jsonb_typeof(v->'value') is distinct from 'number' then raise exception '% needs a numeric value',k; end if;
        n:=(v->>'value')::numeric;
        if n<0 or n>9007199254740991 or n<>trunc(n) then raise exception '% needs a safe nonnegative whole number',k; end if;
        if k='year' and (n<1900 or n>extract(year from today)) then raise exception 'Manufacture year is outside 1900 through current UTC year'; end if;
      elsif v ? 'value' then raise exception 'Unknown/unanswered cannot contain a value'; end if;
    elsif k='registration_state' then
      if jsonb_typeof(v) is distinct from 'object' or exists(select 1 from jsonb_object_keys(v) x where x not in ('state','state_id')) then raise exception 'Invalid registration answer'; end if;
      status:=v->>'state';
      if status is null or status not in ('provided','unknown','not_applicable','unanswered') then raise exception 'Invalid registration state'; end if;
      if status='provided' then
        if jsonb_typeof(v->'state_id') is distinct from 'string' or not exists(select 1 from public.vehicle_registration_states s where s.id=(v->>'state_id')::uuid) then raise exception 'Valid state/UT reference required'; end if;
      elsif v ? 'state_id' then raise exception 'Registration declaration contradicts state/UT'; end if;
    elsif k in ('variant','color','insurance_valid_till') then
      if jsonb_typeof(v) is distinct from 'string' then raise exception '% needs text',k; end if;
      if k='variant' and length(v#>>'{}')>80 or k='color' and length(v#>>'{}')>60 then raise exception '% is too long',k; end if;
      if k='insurance_valid_till' then
        if (v#>>'{}') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'Invalid insurance date'; end if;
        d:=(v#>>'{}')::date;
        if to_char(d,'YYYY-MM-DD')<>v#>>'{}' then raise exception 'Invalid insurance date'; end if;
      end if;
    else
      if k='battery_warranty_left' then
        if jsonb_typeof(v) is distinct from 'object' or exists(select 1 from jsonb_object_keys(v) x where x not in ('months','as_of')) then raise exception 'Invalid battery warranty'; end if;
        v:=v->'months';
      end if;
      if jsonb_typeof(v) is distinct from 'number' then raise exception '% needs a number',k; end if;
      n:=(v#>>'{}')::numeric;
      if n<0 or n>9007199254740991 then raise exception '% outside safe JSON numeric representation',k; end if;
      if k='engine_cc' and n=0 then raise exception 'Engine cc must be positive'; end if;
      if k in ('owner_number','battery_warranty_left') and n<>trunc(n) then raise exception '% needs a whole number',k; end if;
      if k='owner_number' and n<1 then raise exception 'Owner ordinal starts at 1'; end if;
      if k='battery_warranty_left' then
        normalized:=jsonb_set(normalized,array[k],jsonb_build_object('months',n,'as_of',case when previous->k->'months'=to_jsonb(n) then coalesce(previous->k->>'as_of',today::text) else today::text end));
      end if;
    end if;
  end loop;
  return normalized;
end $$;

create function app_security.vehicle_compatibility(raw jsonb,path jsonb,definition jsonb)
returns text language plpgsql immutable set search_path='' as $$
declare electric boolean := (path->>2) like 'Electric %'; m jsonb; type text := raw->>'vehicle_type'; fuel text := raw->>'fuel_type';
begin
  if path->>1='Motorcycles' then
    if type<>(case when electric then 'Electric Motorcycle' else 'Motorcycle' end) then return 'incompatible'; end if;
  elsif electric then
    if type<>'Electric Scooter' then return 'incompatible'; end if;
  elsif type not in ('Scooter','Moped') then return 'incompatible'; end if;
  if electric and fuel<>'Electric' or not electric and fuel not in ('Petrol','CNG') then return 'incompatible'; end if;
  select x into m from jsonb_array_elements(definition->'mappings') x where x->>'vehicleType'=type and x->>'style'=raw->>'category' and (x->>'fuel' is null or x->>'fuel'=fuel);
  if m is not null then return case when m->>'leaf'=path->>2 then 'mapped' else 'incompatible' end; end if;
  return case when definition->'unresolvedStyles' ? (raw->>'category') then 'unresolved' else 'incompatible' end;
end $$;

create function app_security.vehicle_context_guard() returns trigger language plpgsql security definer set search_path='' as $$
declare l public.listings; v public.vehicle_contract_versions; p public.vehicle_category_contracts; r public.vehicle_catalogue_rows; m public.vehicle_models; state text; retained boolean:=false;
begin
  select * into strict l from public.listings where id=new.listing_id;
  if l.category_id<>new.category_id or l.status<>'draft' then raise exception 'Vehicle context must match a draft category'; end if;
  select * into strict v from public.vehicle_contract_versions where id=new.version_id;
  select * into strict p from public.vehicle_category_contracts where category_id=new.category_id and version_id=new.version_id;
  if tg_op='UPDATE' then
    if new.listing_id<>old.listing_id then raise exception 'Listing context identity is immutable'; end if;
    if old.category_id=new.category_id and old.version_id<>new.version_id then raise exception 'Saved contract version cannot silently change'; end if;
    retained:=old.category_id=new.category_id and old.version_id=new.version_id and old.mode=new.mode and old.model_id is not distinct from new.model_id and old.brand_id is not distinct from new.brand_id and old.brand_text is not distinct from new.brand_text and old.model_text is not distinct from new.model_text;
  end if;
  if not retained and (not v.new_assignment_enabled or not exists(select 1 from public.categories c where c.id=new.category_id and c.is_active and c.new_listing_enabled)) then raise exception 'Vehicle category/version closed for new assignment'; end if;
  new.classification_review_required:=new.mode='unresolved';
  if new.mode='not_listed' then
    -- Exact trimmed/case-insensitive recognition, no guessed aliases or fuzzy certification.
    select x.* into m from public.vehicle_models x join public.vehicle_brands b on b.id=x.brand_id where lower(btrim(b.label))=lower(btrim(new.brand_text)) and lower(btrim(x.label))=lower(btrim(new.model_text));
    if found then new.model_id:=m.id; raise exception 'Known brand/model must use its catalogue or unresolved route'; end if;
  elsif new.mode in ('catalogue','unresolved') then
    select * into strict r from public.vehicle_catalogue_rows where snapshot_id=v.snapshot_id and model_id=new.model_id;
    select * into strict m from public.vehicle_models where id=new.model_id and brand_id=new.brand_id;
    state:=app_security.vehicle_compatibility(r.raw,p.source_path,v.definition);
    if state='incompatible' then raise exception 'Known model type, powertrain or mapping incompatible'; end if;
    if not retained and (r.raw->>'status'='Upcoming' or not r.selection_enabled) then raise exception 'Model unavailable for new selection'; end if;
    if state<>(case when new.mode='catalogue' then 'mapped' else 'unresolved' end) then raise exception 'Incorrect model resolution mode'; end if;
  end if;
  return new;
end $$;
create trigger vehicle_context_guard before insert or update on public.listing_vehicle_contexts for each row execute function app_security.vehicle_context_guard();

create function app_security.vehicle_listing_guard() returns trigger language plpgsql security definer set search_path='' as $$
declare fields jsonb; previous jsonb:='{}';
begin
  if tg_op='UPDATE' then
    previous:=old.category_attributes;
    if exists(select 1 from public.listing_vehicle_contexts where listing_id=old.id) and new.category_id<>old.category_id and not exists(select 1 from public.vehicle_category_contracts where category_id=new.category_id) then raise exception 'Vehicle contract cannot be removed through another category'; end if;
  end if;
  if not exists(select 1 from public.vehicle_category_contracts where category_id=new.category_id) then return new; end if;
  if new.status<>'draft' then raise exception 'Two-wheeler review/publication is disabled for this milestone'; end if;
  select p.fields into fields from public.vehicle_category_contracts p join public.listing_vehicle_contexts c on c.category_id=p.category_id and c.version_id=p.version_id where c.listing_id=new.id and c.category_id=new.category_id;
  if fields is null then select p.fields into fields from public.vehicle_category_contracts p join public.vehicle_contract_versions v on v.id=p.version_id where p.category_id=new.category_id and v.contract_key='two-wheeler-draft-v1'; end if;
  new.category_attributes:=app_security.validate_vehicle_answers(new.category_attributes,fields,previous);
  if new.price_type='free' and new.price_paise is distinct from 0 then raise exception 'Free price must be zero'; end if;
  return new;
end $$;
-- Sort after the existing trusted-field and material-edit triggers, preserving their behavior.
create trigger z_vehicle_listing_guard before insert or update on public.listings for each row execute function app_security.vehicle_listing_guard();

create function app_security.vehicle_context_complete() returns trigger language plpgsql security definer set search_path='' as $$
declare listing uuid; l public.listings; c public.listing_vehicle_contexts; fields jsonb;
begin
  if tg_table_name='listings' then listing:=new.id; else listing:=new.listing_id; end if;
  select * into l from public.listings where id=listing;
  if not found then return null; end if;
  select * into c from public.listing_vehicle_contexts where listing_id=listing;
  if exists(select 1 from public.vehicle_category_contracts where category_id=l.category_id) then
    if c.listing_id is null or c.category_id<>l.category_id or l.status<>'draft' then raise exception 'Atomic vehicle context/category required; submission disabled'; end if;
    select p.fields into strict fields from public.vehicle_category_contracts p where p.category_id=c.category_id and p.version_id=c.version_id;
    perform app_security.validate_vehicle_answers(l.category_attributes,fields,l.category_attributes);
  elsif c.listing_id is not null then raise exception 'Vehicle context cannot attach to unrelated category'; end if;
  return null;
end $$;
create constraint trigger vehicle_listing_context_complete after insert or update on public.listings deferrable initially deferred for each row execute function app_security.vehicle_context_complete();
create constraint trigger vehicle_context_listing_complete after insert or update on public.listing_vehicle_contexts deferrable initially deferred for each row execute function app_security.vehicle_context_complete();

-- Invoker: existing listings RLS, auth-derived seller, policy/account and private-location guards apply.
create function public.save_two_wheeler_draft(p_listing_id uuid,p_listing jsonb,p_version_id uuid,p_resolution jsonb)
returns uuid language plpgsql security invoker set search_path='' as $$
#variable_conflict use_variable
declare id uuid; common public.listings; mode text:=p_resolution->>'mode'; brand uuid; model uuid; brand_text text; model_text text;
begin
  if auth.uid() is null then raise exception 'Sign in required'; end if;
  if jsonb_typeof(p_listing) is distinct from 'object' or jsonb_typeof(p_resolution) is distinct from 'object' then raise exception 'Malformed draft payload'; end if;
  if exists(select 1 from jsonb_object_keys(p_listing) x where x not in ('title','description','category_id','city_id','locality_id','condition','price_type','price_paise','pin_code','landmark','category_attributes')) then raise exception 'Unexpected common field'; end if;
  if mode is null or mode not in ('unanswered','catalogue','unresolved','not_listed') then raise exception 'Invalid resolution mode'; end if;
  if exists(select 1 from jsonb_object_keys(p_resolution) x where x not in (select unnest(case when mode='unanswered' then array['mode','brand_id'] when mode='not_listed' then array['mode','brand_text','model_text'] else array['mode','brand_id','model_id'] end))) then raise exception 'Unexpected/forged resolution field'; end if;
  select * into common from jsonb_populate_record(null::public.listings,p_listing);
  if length(btrim(common.title))<3 or length(common.title)>150 then raise exception 'Title must be 3–150 characters'; end if;
  if jsonb_typeof(p_listing->'price_paise')='number' and (p_listing->>'price_paise')::numeric<>trunc((p_listing->>'price_paise')::numeric) then raise exception 'Price paise must be whole'; end if;
  brand:=nullif(p_resolution->>'brand_id','')::uuid; model:=nullif(p_resolution->>'model_id','')::uuid;
  brand_text:=p_resolution->>'brand_text'; model_text:=p_resolution->>'model_text';
  if p_listing_id is null then
    insert into public.listings(title,description,category_id,city_id,locality_id,condition,price_type,price_paise,pin_code,landmark,category_attributes)
    values(common.title,common.description,common.category_id,common.city_id,common.locality_id,common.condition,common.price_type,common.price_paise,common.pin_code,common.landmark,coalesce(common.category_attributes,'{}')) returning listings.id into id;
  else
    -- Row lock serializes same-ID updates, and prevents non-owner and non-vehicle conversion.
    perform 1 from public.listings l join public.listing_vehicle_contexts c on c.listing_id=l.id where l.id=p_listing_id and l.seller_id=auth.uid() and l.status='draft' for update of l;
    if not found then raise exception 'Owned vehicle draft required'; end if;
    update public.listings set title=common.title,description=common.description,category_id=common.category_id,city_id=common.city_id,locality_id=common.locality_id,condition=common.condition,price_type=common.price_type,price_paise=common.price_paise,pin_code=common.pin_code,landmark=common.landmark,category_attributes=coalesce(common.category_attributes,'{}') where listings.id=p_listing_id returning listings.id into id;
    if id is null then raise exception 'Draft update denied'; end if;
  end if;
  if p_listing_id is null then
    insert into public.listing_vehicle_contexts(listing_id,category_id,version_id,mode,brand_id,model_id,brand_text,model_text)
    values(id,common.category_id,p_version_id,mode,brand,model,brand_text,model_text);
  else
    update public.listing_vehicle_contexts set category_id=common.category_id,version_id=p_version_id,mode=mode,brand_id=brand,model_id=model,brand_text=brand_text,model_text=model_text where listing_id=id;
  end if;
  return id;
end $$;
revoke all on function public.save_two_wheeler_draft(uuid,jsonb,uuid,jsonb) from public,anon,service_role;
grant execute on function public.save_two_wheeler_draft(uuid,jsonb,uuid,jsonb) to authenticated;
revoke all on function app_security.validate_vehicle_answers(jsonb,jsonb,jsonb), app_security.vehicle_compatibility(jsonb,jsonb,jsonb), app_security.vehicle_context_guard(),app_security.vehicle_listing_guard(),app_security.vehicle_context_complete() from public,anon,authenticated,service_role;
-- Trigger calls run through their definer. The pure helpers are not exposed as RPCs.

-- Source import: exactly nine paths and 830 rows; UUIDs are generated once in Test.
